mapper.select:
SELECT R1.* FROM( SELECT notice.noticeid, notice.branchid, notice.memberid, notice.category, notice.title, notice.message, DATE_FORMAT(notice.regdate, '%Y-%m-%d %H:%i:%s') regdate, notice.readyn, DATE_FORMAT(notice.readdate, '%Y-%m-%d %H:%i:%s') readdate, notice.needaggreyn, notice.aggreyn, DATE_FORMAT(notice.aggredate, '%Y-%m-%d %H:%i:%s') aggredate FROM ttok.notice notice
AND notice.memberid = #{memberid}
ORDER BY noticeid desc ) R1
LIMIT ${length} OFFSET ${start}
